func TestTranspileComposition(t *testing.T) {
	t.Run("let + fstring + guard together", func(t *testing.T) {
		source := []byte("package main\nimport \"fmt\"\nfunc greet(name string) string {\n\tguard name != \"\" else {\n\t\treturn \"anonymous\"\n\t}\n\tlet greeting = f\"hello {name}\"\n\treturn greeting\n}\nfunc main() { fmt.Println(greet(\"alice\")) }\n")
		goCode, err := ferrouswheel.Transpile(source)

		t.Run("transpiles without error", func(t *testing.T) {
			require.NoError(t, err, "danmuji:748: given let + fstring + guard together > then transpiles without error | expect (expect err == nil)")
		})
		t.Run("all features are present", func(t *testing.T) {
			assert.True(t, strings.Contains(goCode, "if !(name != \"\")"), "danmuji:751: given let + fstring + guard together > then all features are present | expect (expect strings.Contains(goCode, \"if !(name != \\\"\\\")\"))")
			assert.True(t, strings.Contains(goCode, "greeting := fmt.Sprintf"), "danmuji:752: given let + fstring + guard together > then all features are present | expect (expect strings.Contains(goCode, \"greeting := fmt.Sprintf\"))")
		})
		t.Run("no fw keywords remain", func(t *testing.T) {
			assert.False(t, strings.Contains(goCode, "guard "), "danmuji:755: given let + fstring + guard together > then no fw keywords remain | reject (reject strings.Contains(goCode, \"guard \"))")
			assert.False(t, strings.Contains(goCode, "let "), "danmuji:756: given let + fstring + guard together > then no fw keywords remain | reject (reject strings.Contains(goCode, \"let \"))")
		})
	})
	t.Run("enum + impl + derive together", func(t *testing.T) {
		source := []byte("package main\ntype Vec2 struct {\n\tX float64\n\tY float64\n}\nderive Equal for Vec2\nimpl Vec2 {\n\tfunc Add(other Vec2) Vec2 {\n\t\treturn Vec2{X: self.X + other.X, Y: self.Y + other.Y}\n\t}\n}\n")
		goCode, err := ferrouswheel.Transpile(source)

		t.Run("transpiles without error", func(t *testing.T) {
			require.NoError(t, err, "danmuji:765: given enum + impl + derive together > then transpiles without error | expect (expect err == nil)")
		})
		t.Run("generates both Equal and methods", func(t *testing.T) {
			assert.True(t, strings.Contains(goCode, "func (x Vec2) Equal(other Vec2) bool"), "danmuji:768: given enum + impl + derive together > then generates both Equal and methods | expect (expect strings.Contains(goCode, \"func (x Vec2) Equal(other Vec2) bool\"))")
			assert.True(t, strings.Contains(goCode, "func (self Vec2)"), "danmuji:769: given enum + impl + derive together > then generates both Equal and methods | expect (expect strings.Contains(goCode, \"func (self Vec2)\"))")
		})
	})
	t.Run("pipeline + for_in + fstring together", func(t *testing.T) {
		source := []byte("package main\nimport \"fmt\"\nimport \"strings\"\nfunc main() {\n\tnames := []string{\"alice\", \"bob\"}\n\tfor name in names {\n\t\tresult := name |> strings.ToUpper\n\t\tmsg := f\"user: {result}\"\n\t\tfmt.Println(msg)\n\t}\n}\n")
		goCode, err := ferrouswheel.Transpile(source)

		t.Run("transpiles without error", func(t *testing.T) {
			require.NoError(t, err, "danmuji:778: given pipeline + for_in + fstring together > then transpiles without error | expect (expect err == nil)")
		})
		t.Run("pipeline becomes function call", func(t *testing.T) {
			assert.True(t, strings.Contains(goCode, "strings.ToUpper(name)"), "danmuji:781: given pipeline + for_in + fstring together > then pipeline becomes function call | expect (expect strings.Contains(goCode, \"strings.ToUpper(name)\"))")
		})
		t.Run("for-in becomes range", func(t *testing.T) {
			assert.True(t, strings.Contains(goCode, "for _, name := range names"), "danmuji:784: given pipeline + for_in + fstring together > then for-in becomes range | expect (expect strings.Contains(goCode, \"for _, name := range names\"))")
		})
		t.Run("fstring becomes Sprintf", func(t *testing.T) {
			assert.True(t, strings.Contains(goCode, "fmt.Sprintf"), "danmuji:787: given pipeline + for_in + fstring together > then fstring becomes Sprintf | expect (expect strings.Contains(goCode, \"fmt.Sprintf\"))")
		})
	})
}

